request_path.py<pre><code>#!/usr/bin/env python3
from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Request:
    host: str
    path: str
    method: str = "GET"
    headers: dict[str, str] = field(default_factory=dict)
    trace: list[str] = field(default_factory=list)


@dataclass
class Response:
    status: int
    body: str
    trace: list[str]


def stage_dns(req: Request) -&gt; Request:
    # Toy: resolve api.shop.test → lb.shop.internal
    resolved = {"api.shop.test": "lb.shop.internal"}.get(req.host)
    if not resolved:
        raise ValueError(f"DNS NXDOMAIN for {req.host}")
    req.trace.append(f"dns:{req.host}-&gt;{resolved}")
    req.headers["X-Resolved-Target"] = resolved
    return req


def stage_edge(req: Request) -&gt; Request | Response:
    # Cache only GET /static/*
    if req.method == "GET" and req.path.startswith("/static/"):
        req.trace.append("edge:CACHE_HIT")
        return Response(200, "cached-asset", req.trace + ["edge:served"])
    req.trace.append("edge:CACHE_MISS")
    return req


def stage_lb(req: Request) -&gt; Request:
    backends = ["svc-a:8080", "svc-b:8080"]
    backend = backends[len(req.path) % len(backends)]
    req.trace.append(f"lb:chose:{backend}")
    return req


def stage_gateway(req: Request) -&gt; Request:
    token = req.headers.get("Authorization", "")
    if req.path.startswith("/api/") and not token.startswith("Bearer "):
        raise PermissionError("gateway:401 missing bearer token")
    req.trace.append("gateway:auth_ok")
    req.headers["X-Request-Id"] = "req-lab-1"
    return req


def stage_service(req: Request) -&gt; Response:
    if req.path == "/api/health":
        body = "ok"
    elif req.path.startswith("/api/"):
        body = f"hello-from-service path={req.path}"
    else:
        return Response(404, "not-found", req.trace + ["service:404"])
    req.trace.append("service:handled")
    return Response(200, body, req.trace)


def handle(host: str, path: str, method: str = "GET", token: str | None = None) -&gt; Response:
    req = Request(host=host, path=path, method=method)
    if token:
        req.headers["Authorization"] = f"Bearer {token}"
    req = stage_dns(req)
    edged = stage_edge(req)
    if isinstance(edged, Response):
        return edged
    req = stage_lb(edged)
    req = stage_gateway(req)
    return stage_service(req)


def main() -&gt; None:
    lines: list[str] = []

    r1 = handle("api.shop.test", "/static/app.js")
    lines += [
        f"case1_status={r1.status}",
        f"case1_body={r1.body}",
        f"case1_trace={'&gt;'.join(r1.trace)}",
    ]

    r2 = handle("api.shop.test", "/api/health", token="lab")
    lines += [
        f"case2_status={r2.status}",
        f"case2_body={r2.body}",
        f"case2_trace={'&gt;'.join(r2.trace)}",
    ]

    try:
        handle("api.shop.test", "/api/orders")
        lines.append("case3_error=missing")
    except PermissionError as exc:
        lines.append(f"case3_error={exc}")

    report = "\n".join(lines) + "\n"
    print(report, end="")
    open("path-report.txt", "w", encoding="utf-8").write(report)


if __name__ == "__main__":
    main()
</code></pre>

collab_lab.py<pre><code>#!/usr/bin/env python3
"""G-Counter and concurrent add-set merge."""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class GCounter:
    """Grow-only counter: each replica increments its own slot."""

    counts: dict[str, int] = field(default_factory=dict)

    def inc(self, replica: str, n: int = 1) -&gt; None:
        self.counts[replica] = self.counts.get(replica, 0) + n

    def value(self) -&gt; int:
        return sum(self.counts.values())

    def merge(self, other: "GCounter") -&gt; "GCounter":
        keys = set(self.counts) | set(other.counts)
        return GCounter({k: max(self.counts.get(k, 0), other.counts.get(k, 0)) for k in keys})


@dataclass
class AddSet:
    """Add-only set with unique element ids (simplified OR-Set add)."""

    elements: dict[str, str] = field(default_factory=dict)  # elem_id -&gt; value

    def add(self, elem_id: str, value: str) -&gt; None:
        self.elements[elem_id] = value

    def merge(self, other: "AddSet") -&gt; "AddSet":
        merged = dict(self.elements)
        merged.update(other.elements)
        return AddSet(merged)

    def values(self) -&gt; set[str]:
        return set(self.elements.values())


def main() -&gt; None:
    a, b = GCounter(), GCounter()
    a.inc("alice", 3)
    b.inc("bob", 2)
    c = a.merge(b)

    s1, s2 = AddSet(), AddSet()
    s1.add("e1", "sticky-note")
    s2.add("e2", "box")
    s2.add("e1", "sticky-note")  # same id concurrent
    s = s1.merge(s2)

    lines = [
        f"counter_value={c.value()}",
        f"counter_ok={'yes' if c.value() == 5 else 'no'}",
        f"set_values={','.join(sorted(s.values()))}",
        f"set_ok={'yes' if s.values() == {'sticky-note', 'box'} else 'no'}",
        f"collab_ok={'yes' if c.value() == 5 and s.values() == {'sticky-note', 'box'} else 'no'}",
    ]
    report = "\n".join(lines) + "\n"
    print(report, end="")
    open("collab-report.txt", "w", encoding="utf-8").write(report)


if __name__ == "__main__":
    main()
</code></pre>

storage_lab.py<pre><code>#!/usr/bin/env python3
"""Tiny store: primary key + secondary index vs full scan."""

from __future__ import annotations

import time
from dataclasses import dataclass


@dataclass
class Link:
    code: str
    url: str
    owner: str


class LinkStore:
    def __init__(self) -&gt; None:
        self.by_code: dict[str, Link] = {}
        self.by_owner: dict[str, set[str]] = {}

    def put(self, link: Link) -&gt; None:
        old = self.by_code.get(link.code)
        if old is not None:
            self.by_owner.get(old.owner, set()).discard(old.code)
        self.by_code[link.code] = link
        self.by_owner.setdefault(link.owner, set()).add(link.code)

    def get(self, code: str) -&gt; Link | None:
        return self.by_code.get(code)

    def list_by_owner_indexed(self, owner: str) -&gt; list[Link]:
        codes = self.by_owner.get(owner, set())
        return [self.by_code[c] for c in codes if c in self.by_code]

    def list_by_owner_scan(self, owner: str) -&gt; list[Link]:
        return [link for link in self.by_code.values() if link.owner == owner]


def timed(fn, *args, loops: int = 200) -&gt; float:
    start = time.perf_counter()
    for _ in range(loops):
        fn(*args)
    return (time.perf_counter() - start) * 1000 / loops


def main() -&gt; None:
    store = LinkStore()
    owners = [f"user-{i % 50}" for i in range(5_000)]
    for i, owner in enumerate(owners):
        store.put(Link(code=f"c{i:05d}", url=f"https://example.com/{i}", owner=owner))

    target = "user-7"
    indexed_ms = timed(store.list_by_owner_indexed, target)
    scan_ms = timed(store.list_by_owner_scan, target)
    sample = store.get("c00007")

    lines = [
        f"records={len(store.by_code)}",
        f"get_code={sample.code if sample else None}",
        f"owner_indexed_avg_ms={indexed_ms:.4f}",
        f"owner_scan_avg_ms={scan_ms:.4f}",
        f"indexed_faster_x={scan_ms / indexed_ms:.1f}" if indexed_ms else "n/a",
    ]
    report = "\n".join(lines) + "\n"
    print(report, end="")
    open("storage-report.txt", "w", encoding="utf-8").write(report)


if __name__ == "__main__":
